SYSTEM_PROMPT = """You are a release agent.
Never push to main. Always run the suite before you commit.
"""

REASSERT_EVERY = 20


class Agent:
    def __init__(self, client):
        self.client = client
        self.messages = [{"role": "system", "content": SYSTEM_PROMPT}]

    def _reassert_standing_rules(self):
        # Recall of material in the middle of a long transcript degrades, so the
        # standing rules are restated near the end of the window on a cadence.
        self.messages.append(
            {"role": "user", "content": "<standing_rules>" + SYSTEM_PROMPT + "</standing_rules>"}
        )

    def run(self, goal, max_steps=400):
        self.messages.append({"role": "user", "content": goal})
        for step in range(max_steps):
            if step and step % REASSERT_EVERY == 0:
                self._reassert_standing_rules()
            reply = self.client.messages.create(messages=self.messages)
            self.messages.append({"role": "assistant", "content": reply.text})
            if reply.done:
                return reply
            self.messages.append({"role": "user", "content": reply.tool_result})
        return None
